-- 5. ASIGNAR DOCENTES A MATERIAS (round-robin)
SET @rn = 0;
SELECT
    CASE (@rn := @rn + 1) % 7
        WHEN 0 THEN 4
        WHEN 1 THEN 5
        WHEN 2 THEN 6
        WHEN 3 THEN 7
        WHEN 4 THEN 8
        WHEN 5 THEN 9
        WHEN 6 THEN 10
    END,
    cm.id_curso_materia,
    1,
    'activo',
    'FALTA'
FROM curso_materia cm
WHERE cm.estado = 1
ORDER BY cm.id_curso_materia;

